  function inp() { return "w-full border rounded-xl px-3 py-2 bg-transparent"; }

  // ---------------- التخزين ----------------
  function docId(kind) { return "std11_" + kind; }
  function findDoc(kind) { return PF().items.filter(function (x) { return x.id === docId(kind); })[0]; }
  function saveDoc(kind, data, title) {
    var d = db(); if (!d) return Promise.reject(new Error("لا يوجد اتصال بالخدمة"));
    var old = findDoc(kind), doc = { workspaceType: "portfolio-form", formId: "std11-" + kind, title: title, date: today(), data: data, createdAt: old ? old.createdAt || Date.now() : Date.now(), updatedAt: Date.now() };
    return d.collection("portfolio_items").doc(docId(kind)).set(doc).then(function () {
      doc.id = docId(kind); var it = PF().items, i = it.findIndex(function (x) { return x.id === doc.id; }); if (i >= 0) it[i] = doc; else it.unshift(doc); return doc;
    });
  }
